+import { AppError } from "../errors.js";
+
+const cookWrites = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Authenticates a bearer key and checks its role for the requested operation. */
+export function authorize(store, headers, method, path) {
+  const header = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+  const token = typeof header === "string" ? /^Bearer ([^\s]+)$/i.exec(header)?.[1] : null;
+  const identity = token ? store.data.apiKeys.find((entry) => entry.key === token) : null;
+  if (!identity) throw new AppError("unauthorized");
+  const allowed = identity.role === "manager" ||
+    (["viewer", "cook"].includes(identity.role) && method === "GET" && path !== "/audit") ||
+    (identity.role === "cook" && method === "POST" && cookWrites.some((pattern) => pattern.test(path)));
+  if (!allowed) throw new AppError("forbidden");
+  return identity;
+}
