+import test from "node:test";
+import assert from "node:assert/strict";
+import { createApp } from "../src/http/server.js";
+import { fresh, NOW } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}-key` });
+
+test("all requests require a known bearer key", async () => {
+  const handle = createApp(fresh());
+  for (const authorization of [undefined, "Bearer unknown", "Basic seed-manager-key", "Bearer "]) {
+    const response = await handle({ path: "/items", headers: { authorization } });
+    assert.equal(response.status, 401);
+    assert.equal(response.body.error.code, "unauthorized");
+    assert.ok(response.body.error.message);
+  }
+  assert.equal((await handle({ path: "/items", headers: headers("viewer") })).status, 200);
+});
+
+test("viewer reads and only managers may read audit", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const role of ["viewer", "cook"]) {
+    const response = await handle({ path: "/audit", headers: headers(role) });
+    assert.equal(response.status, 403);
+    assert.equal(response.body.error.code, "forbidden");
+  }
+  const response = await handle({ method: "POST", path: "/recipes/1/cook", headers: headers("viewer"), body: { portions: 1 } });
+  assert.equal(response.status, 403);
+  assert.deepEqual(store.data.audit, []);
+  assert.equal((await handle({ path: "/audit", headers: headers("manager") })).status, 200);
+});
+
+test("cook may perform only the four kitchen writes", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  const managerHeaders = headers("manager");
+  const take = await handle({ method: "POST", path: "/stocktakes", headers: managerHeaders, body: { location: "dry" } });
+  for (const [path, body, status] of [
+    ["/recipes/1/cook", { portions: 1 }, 200],
+    ["/batches/1/waste", { qty: 0.1 }, 201],
+    ["/temperatures", { location: "fridge", celsius: 4 }, 201],
+    [`/stocktakes/${take.body.id}/counts`, { batchId: 6, counted: 12 }, 200],
+  ]) {
+    assert.equal((await handle({ method: "POST", path, body, headers: headers("cook") })).status, status);
+  }
+  for (const [method, path] of [
+    ["POST", "/stocktakes"], ["POST", `/stocktakes/${take.body.id}/finish`],
+    ["POST", "/orders"], ["POST", "/prices"], ["POST", "/dishes"],
+    ["PUT", "/items/1/allergens"], ["POST", "/jobs/nightly"],
+    ["POST", "/import/items"], ["POST", "/outbox/1/sent"],
+  ]) {
+    assert.equal((await handle({ method, path, headers: headers("cook") })).status, 403);
+  }
+});
+
+test("successful writes save audit with the data once and list newest first", async () => {
+  const store = fresh();
+  let saves = 0;
+  store.save = () => {
+    saves++;
+    assert.equal(store.data.audit.length, saves);
+  };
+  const handle = createApp(store, { clock: () => NOW + saves * 1000 });
+  for (let i = 0; i < 2; i++) {
+    await handle({ method: "POST", path: "/temperatures", headers: headers("cook"), body: { location: "fridge", celsius: 4 } });
+  }
+  const response = await handle({ path: "/audit", headers: headers("manager") });
+  assert.deepEqual(response.body, [
+    { time: new Date(NOW + 1000).toISOString(), name: "Seed cook", method: "POST", path: "/temperatures", status: 201 },
+    { time: new Date(NOW).toISOString(), name: "Seed cook", method: "POST", path: "/temperatures", status: 201 },
+  ]);
+  await handle({ method: "POST", path: "/temperatures", headers: headers("cook"), body: {} });
+  assert.equal(saves, 2);
+  assert.equal(store.data.audit.length, 2);
+});
